<?php

declare(strict_types=1);

namespace Nyoncode\BackupManager\Mcp;

use Closure;

/**
 * A ready-made instruction a user can pick in an MCP client ("set up backups").
 *
 * The text is generated by a closure so a prompt always reflects the live
 * installation — which profiles exist, what is already configured.
 */
final readonly class McpPrompt
{
    /**
     * @param  Closure(): string  $renderer
     */
    public function __construct(
        public string $name,
        public string $title,
        public string $description,
        private Closure $renderer,
    ) {}

    /**
     * @return list<array<string, mixed>>
     */
    public function messages(): array
    {
        return [[
            'role' => 'user',
            'content' => ['type' => 'text', 'text' => ($this->renderer)()],
        ]];
    }

    /**
     * @return array<string, mixed>
     */
    public function toArray(): array
    {
        return [
            'name' => $this->name,
            'title' => $this->title,
            'description' => $this->description,
            'arguments' => [],
        ];
    }
}
